#include "exercise.h"
#include <assert.h>
#include <math.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
static bool positive(int x) { return x > 0; }
static bool bstring(const void *p) { return (*(const char *const *)p)[0] == 98; }
static void string_length(const void *p, void *out) {
    *(size_t *)out = strlen(*(const char *const *)p);
}
int main(void) {
    const char *c[] = {"Isla", "Tariq"}, *d[] = {"Uma"}, *e[] = {"Kevin"};
    family f[] = {{"Helena", c, 2}, {"Isla", d, 1}, {"Erdos", e, 1}};
    assert(degree_of_separation(f, 3, "Tariq", "Uma") == 2);
    assert(degree_of_separation(f, 3, "Isla", "Tariq") == 1);
    assert(degree_of_separation(f, 3, "Isla", "Kevin") == -1);
    assert(degree_of_separation(f, 3, "Missing", "Uma") == -2);
    assert(degree_of_separation(f, 3, "Uma", "Missing") == -3);

    return 0;
}
